function injectHtmlExtras(html, directoryHint = null) {
  let out = html
  // Always refresh bootstrap so older cached injects are replaced.
  out = out.replace(/<script id="cortex-directory-bootstrap">[\s\S]*?<\/script>/g, "")
  out = out.replace(/<div id="cortex-project-hud"[\s\S]*?<\/div>/g, "")
  out = out.replace(/<style id="cortex-project-hud-style">[\s\S]*?<\/style>/g, "")
  if (out.includes('<script type="module"')) {
    out = out.replace('<script type="module"', `${DIRECTORY_BOOTSTRAP}<script type="module"`)
  } else if (out.includes("</head>")) {
    out = out.replace("</head>", `${DIRECTORY_BOOTSTRAP}</head>`)
  } else {
    out = DIRECTORY_BOOTSTRAP + out
  }
  if (!out.includes('id="cortex-mobile-composer"')) {
    out = out.replace("</head>", `${MOBILE_CSS}${MOBILE_SCRIPT}</head>`)
  }
  const pathText = directoryHint || "(project)"
  const hud = PROJECT_HUD_HTML(pathText)
  if (out.includes('<div id="root"')) {
    out = out.replace('<div id="root"', `${hud}<div id="root"`)
  } else if (out.includes("<body")) {
    out = out.replace(/<body([^>]*)>/, `<body$1>${hud}`)
  }
  return out
}

function pipeUpstreamResponse(upstream, res, requestPath, acceptsGzip, directoryHint = null) {
  const contentType = String(upstream.headers["content-type"] || "")

  if (isHtml(contentType)) {
    const chunks = []
    upstream.on("data", (chunk) => chunks.push(chunk))
    upstream.on("end", () => {
      const hint = directoryHint || directoryFromPathname(String(requestPath || "").split("?")[0])
      let html = injectHtmlExtras(Buffer.concat(chunks).toString("utf8"), hint)
      const headers = copyResponseHeaders(upstream.headers)
      headers["cache-control"] = "no-store"
      const body = compressIfNeeded(acceptsGzip, Buffer.from(html), headers)
      if (hint) {
        sendWithOptionalDirectoryCookie(res, upstream.statusCode || 502, headers, body, toWindowsDirectory(hint))
      } else {
        res.writeHead(upstream.statusCode || 502, headers)
        res.end(body)
      }
    })
    return
  }

  if (isJson(contentType)) {
    const chunks = []
    upstream.on("data", (chunk) => chunks.push(chunk))
    upstream.on("end", () => {
      let body = Buffer.concat(chunks)
      if (requestPath === "/provider" && upstream.statusCode === 200) {
        const headers = copyResponseHeaders(upstream.headers)
        headers["cache-control"] = "public, max-age=300"
        headers["vary"] = "Accept-Encoding"
        providerCache = { raw: body, gzip: gzipSync(body), headers, expiresAt: Date.now() + PROVIDER_CACHE_TTL_MS }
        sendProviderResponse(res, providerCache, acceptsGzip)
        return
      }
      try {
        const rewritten = rewriteJsonPaths(JSON.parse(body.toString("utf8")))
        body = Buffer.from(JSON.stringify(rewritten))
      } catch {
        // Some JSON-adjacent responses are intentionally passed through unchanged.
      }
      const headers = copyResponseHeaders(upstream.headers)
      headers["cache-control"] = "no-store"
      const compressed = compressIfNeeded(acceptsGzip, body, headers)
      res.writeHead(upstream.statusCode || 502, headers)
      res.end(compressed)
    })
    return
  }

  res.writeHead(upstream.statusCode || 502, copyResponseHeaders(upstream.headers))
  upstream.pipe(res)
}

function compressIfNeeded(acceptsGzip, body, headers) {
  if (!acceptsGzip || body.length < GZIP_MIN_BYTES) {
    headers["content-length"] = body.length
    return body
  }
  const gzip = gzipSync(body)
  headers["content-encoding"] = "gzip"
  headers["content-length"] = gzip.length
  headers["vary"] = "Accept-Encoding"
  return gzip
}

function directoryCookieHeader(directory) {
  if (!directory) return null
  return `${DIR_COOKIE}=${encodeURIComponent(directory)}; Path=/; Max-Age=2592000; SameSite=Lax`
}

function sendWithOptionalDirectoryCookie(res, status, headers, body, directory) {
  const out = { ...headers }
  const cookie = directoryCookieHeader(directory)
  if (cookie) {
    const prev = out["set-cookie"]
    out["set-cookie"] = prev ? (Array.isArray(prev) ? [...prev, cookie] : [prev, cookie]) : cookie
  }
  res.writeHead(status, out)
  res.end(body)
}

